package com.sudoplatform.sudoprivacyinteraction.internal.domain.entities.analysisResult

/**
 * Input for [AnalysisResultService.list].
 *
 * @property virtualPresenceId [String] The identifier of the virtual presence to list analysis
 *  results for.
 * @property limit [Int] Number of records to return.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListAnalysisResultsInput(
    val virtualPresenceId: String,
    val limit: Int? = null,
    val nextToken: String? = null,
)

/**
 * Output for [AnalysisResultService.list].
 *
 * @property items [List] The list of analysis results retrieved in this query.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListAnalysisResultsOutput(
    val items: List<AnalysisResultEntity>,
    val nextToken: String? = null,
)

/**
 * Core entity representation of an analysis result service used in business logic.
 */
internal interface AnalysisResultService {
    /**
     * Retrieve a single analysis result by ID.
     *
     * @param id [String] The unique identifier of the analysis result.
     * @return The [AnalysisResultEntity], or `null` if not found.
     */
    suspend fun get(id: String): AnalysisResultEntity?

    /**
     * Retrieve a list of analysis results associated with a virtual presence.
     *
     * @param input [ListAnalysisResultsInput] Parameters used to list analysis results.
     * @return A [ListAnalysisResultsOutput] of analysis results matching the search criteria.
     */
    suspend fun list(input: ListAnalysisResultsInput): ListAnalysisResultsOutput
}
